@id("close-after-human-approval-via-approval-record")
permit (principal, action == Drupe::Action::"close_workorder", resource)
when { context.input.site_id == "MAIN" }
when temporal {
  formerly within 1h Drupe::Action::"get_approval_record"::response{
    eventResource: resource,
    input.wonum: context.input.wonum,
    input.site_id: context.input.site_id,
    output.decision: Drupe::get_approval_record_Output_decision::"SIGNED_OFF",
    output.approver_kind: Drupe::get_approval_record_Output_approver_kind::"OPERATOR"
  }
};

@id("close-after-human-approval-via-authority")
permit (principal, action == Drupe::Action::"close_workorder", resource)
when { context.input.site_id == "MAIN" }
when temporal {
  formerly within 1h Drupe::Action::"authority_get_approval"::response{
    eventResource: resource,
    input.wonum: context.input.wonum,
    input.site_id: context.input.site_id,
    output.decision: "SIGNED_OFF",
    output.approver_kind: "OPERATOR"
  }
};
